  async function manual(event:SubmitEvent){event.preventDefault();busy=true;error='';try{let from:Date,to:Date,breaks:{started_at:string;ended_at:string}[];
    if(showCorrection){from=new Date(manualFrom);to=new Date(manualTo);if(!Number.isFinite(from.getTime())||!Number.isFinite(to.getTime())||to<=from)throw new Error('Bitte geben Sie einen gültigen Zeitraum mit Ende nach dem Beginn ein.');if(!pausesReviewed)throw new Error('Bestätigen Sie bitte, dass alle tatsächlichen Pausen vollständig angegeben sind.');breaks=manualPauses.map(p=>({started_at:new Date(p.from).toISOString(),ended_at:new Date(p.to).toISOString()})).sort((a,b)=>Date.parse(a.started_at)-Date.parse(b.started_at));let previousEnd=from.getTime();for(const pause of breaks){const start=Date.parse(pause.started_at),end=Date.parse(pause.ended_at);if(start<previousEnd||end<=start||end>to.getTime())throw new Error('Pausen müssen innerhalb der Arbeitszeit liegen, ein späteres Ende haben und dürfen sich nicht überschneiden.');previousEnd=end;}if(correctionReason.trim().length<5)throw new Error('Beschreiben Sie bitte den Grund der Korrektur mit mindestens fünf Zeichen.');}
    else{manualTried=true;const plan=manualPlan;const missing=Object.keys(plan.errors);if(missing.length||!plan.from||!plan.to)throw new Error('Bitte ergänzen oder prüfen: '+missing.map(key=>manualFieldNames[key]??key).join(', ')+'.');from=plan.from;to=plan.to;breaks=plan.breaks;}
    const allocations=showCorrection&&manualAllocations.length?manualAllocations.map(a=>({started_at:new Date(a.from).toISOString(),ended_at:new Date(a.to).toISOString(),order_id:a.order_id||null,activity:a.activity})):undefined;const originals=receipts.filter(c=>c.time_session_id===(correctionSource?.id||timerState?.session_id)&&!['confirmed','resolved'].includes(c.sync_status));const snapshot={started_at:from.toISOString(),ended_at:to.toISOString(),breaks,order_id:showCorrection?manualOrderId||null:manualOrderId===noOrder?null:manualOrderId||null,activity:showCorrection?activity:manualActivity,allocations,reason:manualNote};await command(showCorrection?'workforce.time.propose_correction':'workforce.time.manual',showCorrection?correctionSource?.id||timerState?.session_id||undefined:undefined,{...snapshot,reason:showCorrection?correctionReason:manualNote,new_snapshot:showCorrection?snapshot:undefined,original_command_ids:originals.map(c=>c.command_id),original_commands:originals.map(({sync_status,error,result,received_at,attempts,resolution,...raw})=>raw),timezone:'Europe/Berlin'},showCorrection?correctionSource?.version:undefined);notice=showCorrection?'Der Korrekturantrag wurde gespeichert. Die Originalaufzeichnungen bleiben erhalten.':'Die nacherfasste Zeit wurde gespeichert.';showManual=false;showCorrection=false;day=businessDate(from);await goto('/time?date='+encodeURIComponent(day),{reset:false});await refreshAll().catch(()=>{});}catch(e){error=e instanceof Error?e.message:'Nacherfassung fehlgeschlagen.';}finally{busy=false;}}

</script>
{#snippet orderLine(name:string)}{@const parts=orderParts(name)}<span class="order-line" title={name}><strong>{parts.number}</strong>{#if parts.title}<span class="order-title">{` · ${parts.title}`}</span>{/if}</span>{/snippet}
{#snippet fieldError(key:string)}{#if manualErrors[key]}<span class="field-error" id={`manual-${key}-error`}>{manualErrors[key]}</span>{/if}{/snippet}
<div class="time-view">
<div class="page-heading" data-tour="time-heading"><div><h1>{reviewing?'Teamzeiten prüfen':'Meine Arbeitszeit'}</h1><p class="heading-intro">{reviewing?'Prüfen Sie eingereichte Zeiten, Tätigkeiten und Rückfragen. Eigene Zeiten erfassen Sie im Reiter Meine Arbeitszeit.':'Zeiten erfassen, den Tagesverlauf prüfen und zur Freigabe abgeben.'}</p></div>{#if !reviewing}<div class="page-heading-actions heading-manual"><button class="btn" onclick={()=>openManual(data.summary?.manualAssignment??null)}><Icon name="plus" size={16}/>Zeit nachtragen</button></div>{/if}</div>
{#if error}<div class="notice error" role="alert"><Icon name="alert"/><div>{error}</div></div>{/if}{#if notice}<div class="notice info" role="status"><Icon name={pending.length?'clock':'check'}/><div>{notice}</div></div>{/if}
{#if !reviewing&&data.connected&&data.context?.employeeId===null}<div class="notice warning"><Icon name="users"/><div>Ihr Zugang ist noch keinem Beschäftigtenprofil zugeordnet. Die Verwaltung muss diese Zuordnung für die serverseitige Bestätigung ergänzen. Lokale tatsächliche Aufzeichnungen bleiben erhalten.</div></div>{/if}
{#if data.context?.permissions.includes('time.approve')}<nav class="tabs" aria-label="Arbeitszeitbereiche"><a class="tab" class:active={page.url.searchParams.get('tab')!=='review'} href="/time">Meine Arbeitszeit</a><a class="tab" class:active={page.url.searchParams.get('tab')==='review'} href="/time?tab=review">Teamzeiten prüfen <span class="count">{(data.related?.review_submissions?.length??0)+(data.related?.review_corrections?.length??0)}</span></a></nav>{/if}
{#if page.url.searchParams.get('tab')==='review'&&data.context?.permissions.includes('time.approve')}<TimeReview {data}/>{:else}<div class="time-grid"><div class="stack">
  {#if finishedToday}<section class="finish-card" aria-labelledby="finish-title" tabindex="-1" bind:this={finishCard}>
    <div class="finish-text"><h2 id="finish-title">Feierabend</h2><p>Heute <strong>{hoursText(dayWorkSeconds)}</strong> gearbeitet, <strong>{hoursText(dayBreakSeconds)}</strong> Pause</p></div>
    {#if submissionIds.length}<button class="btn primary" disabled={busy} onclick={()=>submitReview=true}>Jetzt Tag prüfen & abgeben<Icon name="arrow" size={16}/></button>
    {:else if submissionBadge}<p class="submission-badge {submissionBadge.tone}" tabindex="-1"><Icon name={submissionBadge.icon} size={16}/><span>{submissionBadge.text}</span></p>{/if}
  </section>{/if}
  <section class="timer-panel timer-hero" aria-labelledby="timer-title"><h2 id="timer-title" class="sr-only">Stoppuhr für die Arbeitszeit</h2>
    <div class="timer-topline"><span class="eyebrow">{timerState?.status==='work'?'Arbeit läuft':timerState?.status==='break'?'Sie machen Pause':timerState?.status==='finished'?'Arbeitstag beendet':'Bereit für Ihren Arbeitstag'}</span><p class="sync-line {syncView.tone}" role="status" title={timerState?.last_server_at?`Letzter Abgleich ${new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit'}).format(new Date(timerState.last_server_at))}`:undefined}><Icon name={syncView.icon} size={14} class={syncView.icon==='refresh'?'spin':''}/><span>{syncView.text}</span></p></div>
    {#if syncDetail}<p class="sync-detail">{syncDetail}</p>{/if}
    <div class="timer-readout" aria-label={`${Math.floor(elapsed/3600)} Stunden ${Math.floor(elapsed%3600/60)} Minuten Arbeitszeit`}>{durationLabel(elapsed)}</div>
    {#if timerState?.started_at}<p class="timer-description">Beginn {formatClock(timerState.started_at,businessDate(new Date(now)))} · Pause {durationText(breakSeconds)}</p>{:else}<p class="timer-description timer-intro">Wählen Sie bei Bedarf einen Auftrag und starten Sie die Arbeit. Erfassen Sie jede tatsächliche Pause über „Pause“.</p>{/if}
    {#if ['work','break'].includes(timerState?.status||'')&&!showSwitch}<div class="current-assignment">{#if timerState?.order_id}{@render orderLine(orderName(timerState.order_id))}{:else}<span class="order-line">Noch keinem Auftrag zugeordnet</span>{/if}<span class="current-activity">{display(timerState?.activity||'general','activity')}</span></div>{/if}
    {#if !['work','break'].includes(timerState?.status||'')||showSwitch}<div class="field-grid timer-fields"><div class="field"><label for="time-order">Auftrag</label><select use:searchableSelect={orderId} id="time-order" bind:value={orderId}><option value="">Auftrag später zuordnen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div><div class="field"><label for="time-activity">Tätigkeit</label><select use:searchableSelect={activity} id="time-activity" bind:value={activity}>{#each activities as item}<option value={item}>{item}</option>{/each}</select></div></div>{/if}
    <div class="timer-actions">{#if !ready}<button class="btn primary large" disabled><Icon name="refresh" class="spin"/>Zeitspeicher wird geöffnet …</button>{:else if showSwitch}<button class="btn primary large" disabled={busy} onclick={()=>operate('switch')}>Auftrag wechseln<Icon name="arrow"/></button><button class="btn large" onclick={()=>showSwitch=false}>Abbrechen</button>{:else if timerState?.status==='work'}<button class="btn primary large" disabled={busy} onclick={()=>operate('pause')}><Icon name="pause"/>Pause</button><button class="btn large" disabled={busy} onclick={()=>showSwitch=true}><Icon name="briefcase"/>Wechseln</button><button class="btn large" disabled={busy} onclick={()=>operate('finish')}><Icon name="stop"/>Feierabend</button>{:else if timerState?.status==='break'}<button class="btn primary large" disabled={busy} onclick={()=>operate('resume')}><Icon name="play"/>Weiterarbeiten</button><button class="btn large" disabled={busy} onclick={()=>operate('finish')}><Icon name="stop"/>Feierabend</button>{:else}<button class="btn primary large full" disabled={busy} onclick={()=>operate('start')}><Icon name="play"/>Arbeit starten</button>{/if}</div>
  </section>
  <button class="btn mobile-manual" onclick={()=>openManual(data.summary?.manualAssignment??null)}><Icon name="plus" size={16}/>Zeit nachtragen</button>
  <section class="panel"><header class="panel-header"><div><h2>Tagesverlauf</h2>{#if daySegments.length}<p class="day-totals">Arbeit <strong>{durationText(dayWorkSeconds)}</strong> · Pausen <strong>{durationText(dayBreakSeconds)}</strong></p>{/if}</div><div class="field"><label class="sr-only" for="time-day">Tag auswählen</label><input id="time-day" type="date" bind:value={day} onchange={selectDay}/></div></header><div class="panel-body">{#if effectiveCorrections.some(c=>businessDate(c.new_snapshot.session?.started_at)===day)}<p class="field-help mb">Dieser Verlauf zeigt die freigegebenen Korrekturen. Die unveränderten Originalaufzeichnungen können Sie in der jeweiligen Sitzung darunter öffnen.</p>{/if}{#each daySegments as segment}{@const names=segmentOrders(segment)}{@const kinds=segmentActivity(segment)}<div class="time-segment"><div class="segment-kind" class:break={segment.kind==='break'}><Icon name={segment.kind==='break'?'pause':'briefcase'} size={16}/></div><div class="segment-info">{#if names.length}<div class="segment-orders">{#each names as name}{@render orderLine(name)}{/each}</div>{:else}<strong>{segmentFallback(segment)}</strong>{/if}<p>{clockTime(segment.start_at)} – {segment.end_at?clockTime(segment.end_at):'läuft'}{kinds?` · ${kinds}`:''}</p></div><span class="segment-duration">{durationText(durationSeconds([segment],now,segment.kind))}</span></div>{/each}{#if !daySegments.length}<div class="empty-state compact"><div class="empty-icon"><Icon name="clock"/></div><h3>Für diesen Tag noch keine Zeit</h3><p>Tragen Sie einen bereits geleisteten Zeitraum nach. Für eine neue Aufzeichnung öffnen Sie die Stoppuhr.</p></div>{/if}</div>
    <footer class="panel-footer day-footer">
      {#if submissionBadge}<div class="submission-badge {submissionBadge.tone}" tabindex="-1" bind:this={dayBadge}><Icon name={submissionBadge.icon} size={16}/><span>{submissionBadge.text}{#if submissionBadge.detail}<small>{submissionBadge.detail}</small>{/if}</span></div>{/if}
      {#if submissionIds.length||!submissionBadge}<span class="small muted">{selectedDayRunning?'Zum Abgeben zuerst Feierabend erfassen.':submissionIds.length?'Prüfen Sie Tätigkeit, Zuordnung und tatsächliche Pausen.':'Für diesen Tag gibt es noch nichts abzugeben.'}</span><button class="btn primary" disabled={busy||selectedDayRunning||!submissionIds.length} onclick={()=>submitReview=true}>Tag prüfen & abgeben<Icon name="arrow" size={16}/></button>{/if}
    </footer></section>
  {#if dayAllocations.length}<TimeAssignments allocations={dayAllocations} {data}/>{/if}
  <TimeSessionHistory {data} {day} oncorrect={openCorrection}/><WorkReport {data} initialOrderId={orderId} {activity}/>{#if !data.context?.permissions.includes('time.approve')}<TimeReview {data}/>{/if}</div><aside class="stack"><section class="panel"><header class="panel-header"><h2>Übertragung & Klärung</h2><button class="btn small" disabled={syncing} onclick={manualSync}><Icon name="refresh" size={16} class={syncing?'spin':''}/>{syncing?'Wird übertragen …':'Synchronisieren'}</button></header><div class="panel-body">{#each pending as receipt}<div class="sync-row"><strong>{receipt.command_name.replace('workforce.time.','')==='start'?'Arbeit starten':receipt.command_name.endsWith('pause')?'Pause':receipt.command_name.endsWith('resume')?'Weiterarbeit':receipt.command_name.endsWith('switch')?'Auftragswechsel':'Feierabend'}</strong><div class="sync-details"><span>{display(receipt.occurred_at,'occurred_at')}</span><Status value={receipt.sync_status}/></div>{#if receipt.error}<p class="small mt">{typeof receipt.error==='string'?receipt.error:receipt.error.message}</p>{/if}</div>{/each}{#if !pending.length}<p class="small">Keine ausstehenden Übertragungen. Bestätigte Zeiten und genehmigte Klärungen sind im Serverbestand gespeichert.</p>{/if}{#if resolvedReceipts.length}<details class="mt"><summary class="small">Zuletzt geklärte Originalaufzeichnungen ({resolvedReceipts.length})</summary>{#each resolvedReceipts.slice(-20) as receipt}<div class="sync-row"><Status value="resolved"/><p class="small mt">Aufgezeichnet: {displayTimestamp(receipt.occurred_at)}</p><p class="field-help">Freigegeben am {displayTimestamp(receipt.resolution?.approved_at)} · Korrekturbeleg {receipt.resolution?.correction_id}</p><details class="mt"><summary class="field-help">Unveränderte Rohaufzeichnung und Klärungsverweis</summary><pre class="json-preview mt">{JSON.stringify(receipt,null,2)}</pre></details></div>{/each}</details>{/if}{#if conflicts.length}<div class="notice warning mt"><Icon name="alert"/><div>Die Rohaufzeichnungen bleiben erhalten. Stellen Sie einen begründeten Korrekturantrag oder melden Sie sich erneut an. Klicken Sie nach der Freigabe auf „Synchronisieren“, um den Klärungsstand zu übernehmen.</div></div>{#each conflictGroups as sessionId}<button class="btn full mt" onclick={()=>openCorrection(conflictSource(sessionId))}>Aufzeichnungen vom {display(conflictSource(sessionId).started_at,'date')} klären</button>{/each}{/if}</div></section><section class="panel"><header class="panel-header"><h2>Mein Zeitkonto</h2></header><div class="panel-body"><dl class="definition-list"><div><dt>Freigegebene Stunden</dt><dd>{data.summary?.approvedHours??'—'}</dd></div><div><dt>Saldo</dt><dd>{data.summary?.timeBalance??'—'}</dd></div><div><dt>Urlaub verfügbar</dt><dd>{data.summary?.leaveBalance!=null?`${data.summary.leaveBalance} Tage`:'Nicht hinterlegt'}</dd></div>{#if data.summary?.timeBalanceAsOf}<div><dt>Saldo bis einschließlich</dt><dd>{display(data.summary.timeBalanceAsOf,'date')}</dd></div>{/if}<div><dt>Anträge</dt><dd><a class="text-link" href="/leave">Eigene Anträge<Icon name="arrow" size={14}/></a></dd></div></dl>{#if data.summary?.timeBalanceMessage}<p class="field-help mt">{data.summary.timeBalanceMessage}</p>{/if}</div></section><section class="panel"><header class="panel-header"><h2>Arbeiten ohne Internet</h2></header><div class="panel-body"><details><summary>Gerätespeicher und Übertragung</summary><p class="small mt">Auf diesem Gerät werden nur Ihre eigenen Zeitaufzeichnungen und die erforderlichen Auftragskurzangaben vorgehalten. Synchronisieren Sie nach einer Baustelle zeitnah.</p>{#if !storagePersistent}<button class="btn full mt" onclick={persist}><Icon name="lock" size={15}/>Browserspeicher anfragen</button>{:else}<p class="small mt">Der Browser hat dauerhaften Speicher gewährt.</p>{/if}<p class="field-help mt">Gelöschte Browserdaten können nicht wiederhergestellt werden. Ein geschlossener Browser garantiert keine Hintergrundübertragung.</p></details></div></section></aside></div>
{/if}
</div>
{#if showManual}<div class="modal-backdrop" role="presentation"><div class="modal" role="dialog" use:focusTrap aria-modal="true" aria-labelledby="manual-title" tabindex="-1" onkeydown={(e)=>{if(e.key==='Escape'&&!busy)showManual=false;}}><header class="modal-header"><div><h2 id="manual-title">{showCorrection?'Korrekturantrag':'Zeit nachtragen'}</h2><p>{showCorrection?'Geben Sie den tatsächlichen Arbeitszeitraum an. Auffälligkeiten werden zur Prüfung markiert.':'Für einen Zeitraum, den Sie nicht gestempelt haben. Auffälligkeiten werden zur Prüfung markiert.'}</p></div><button class="icon-button" onclick={()=>showManual=false} aria-label="Schließen" disabled={busy}><Icon name="close"/></button></header><form onsubmit={manual} style="display:contents" novalidate={!showCorrection}><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}
  {#if !showCorrection}<div class="field-grid manual-simple">
    {#if manualAssignment}<p class="field-help full">Aus dem Einsatz übernommen: {manualAssignment.order_name}. Ergänzen Sie die tatsächlichen Uhrzeiten.</p>{/if}
    <div class="field full"><label for="manual-date">Tag *</label><div class="day-pick"><input id="manual-date" type="date" max={today} bind:value={manualDate} required aria-invalid={manualErrors.date?'true':undefined} aria-describedby={manualErrors.date?'manual-date-error':undefined}/><button type="button" class="chip" aria-pressed={manualDate===today} onclick={()=>manualDate=today}>Heute</button><button type="button" class="chip" aria-pressed={manualDate===shiftDay(today,-1)} onclick={()=>manualDate=shiftDay(today,-1)}>Gestern</button></div>{@render fieldError('date')}</div>
    <div class="field-pair full"><div class="field"><label for="manual-start">Beginn *</label><input id="manual-start" type="time" bind:value={manualStartTime} required aria-invalid={manualErrors.start?'true':undefined} aria-describedby={manualErrors.start?'manual-start-error':undefined}/>{@render fieldError('start')}</div><div class="field"><label for="manual-end">Ende *</label><input id="manual-end" type="time" bind:value={manualEndTime} required aria-invalid={manualErrors.end?'true':undefined} aria-describedby={manualErrors.end?'manual-end-error':manualPlan.overnight?'manual-end-help':undefined}/>{#if manualErrors.end}{@render fieldError('end')}{:else if manualPlan.overnight}<span class="field-help" id="manual-end-help">Ende am Folgetag, {dayText(shiftDay(manualDate,1))}</span>{/if}</div></div>
    <fieldset class="field full chip-field" aria-describedby={manualErrors.pause?'manual-pause-error':undefined}><legend>Pause in Minuten *</legend><div class="chips">{#each pauseChoices as minutes}<label class="chip"><input type="radio" name="manual-pause" value={minutes} bind:group={manualPause}/>{minutes}</label>{/each}<label class="chip"><input type="radio" name="manual-pause" value="custom" bind:group={manualPause}/>Andere</label></div>
      {#if manualPause==='custom'}<div class="field"><label for="manual-pause-minutes">Pause in Minuten</label><input id="manual-pause-minutes" type="number" inputmode="numeric" min="0" max="720" step="1" bind:value={manualPauseCustom}/></div>{/if}
      {#if manualPlan.pauseFrom&&!manualErrors.pause}<p class="field-help">Pause {manualClock(manualPlan.pauseFrom)}–{manualClock(manualPlan.pauseTo)}{editPauseStart?'':', mittig eingetragen'}{#if !editPauseStart}{' · '}<button type="button" class="inline-link" onclick={startPauseEdit}>Beginn ändern</button>{/if}</p>{/if}
      {#if editPauseStart&&manualPlan.minutes>0}<div class="field"><label for="manual-pause-start">Pause ab</label><input id="manual-pause-start" type="time" bind:value={manualPauseStart}/></div>{/if}
      {@render fieldError('pause')}</fieldset>
    <div class="field full"><label for="manual-order">Auftrag *</label><select use:searchableSelect={manualOrderId} id="manual-order" bind:value={manualOrderId} required aria-invalid={manualErrors.order?'true':undefined} aria-describedby={manualErrors.order?'manual-order-error':undefined}><option value="">Bitte auswählen</option><option value={noOrder}>Ohne Auftrag (betriebliche Arbeit)</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select>{@render fieldError('order')}</div>
    <div class="field full"><label for="manual-activity">Tätigkeit *</label><select use:searchableSelect={manualActivity} id="manual-activity" bind:value={manualActivity} required aria-invalid={manualErrors.activity?'true':undefined}>{#each activities as item}<option value={item}>{item}</option>{/each}</select>{@render fieldError('activity')}</div>
    <div class="field full"><label for="manual-note">Anlass *</label><input id="manual-note" bind:value={manualNote} required minlength="3" maxlength="200" autocomplete="off" placeholder="z. B. Vergessen zu stempeln" aria-invalid={manualErrors.reason?'true':undefined} aria-describedby={manualErrors.reason?'manual-reason-error':undefined}/><div class="chips">{#each reasonChoices as reason}<button type="button" class="chip" aria-pressed={manualNote===reason} onclick={()=>manualNote=reason}>{reason}</button>{/each}</div>{@render fieldError('reason')}</div>
    {#if manualPlan.from&&manualPlan.to&&manualPlan.work>0}<p class="manual-preview full" aria-live="polite">Arbeitszeit <strong>{hoursText(manualPlan.work)}</strong> · {manualClock(manualPlan.from)}–{manualClock(manualPlan.to)}{manualPlan.minutes>0?` · ${manualPlan.minutes} min Pause`:' · ohne Pause'}</p>{/if}
  </div>
  {:else}<div class="field-grid"><div class="field"><label for="manual-from">Arbeitsbeginn *</label><input id="manual-from" type="datetime-local" step="1" bind:value={manualFrom} required/></div><div class="field"><label for="manual-to">Arbeitsende *</label><input id="manual-to" type="datetime-local" step="1" bind:value={manualTo} onchange={()=>alignManualEnd(manualTo)} required/></div><div class="field full"><span class="field-label">Tatsächliche Pausen</span><p class="field-help">Geben Sie Beginn und Ende jeder Pause ein. Wenn Sie keine Pause gemacht haben, genügt die Bestätigung.</p>{#each manualPauses as pause,index}<div class="manual-pause"><div class="field"><label for={`pause-from-${pause.id}`}>Pause {index+1} von *</label><input id={`pause-from-${pause.id}`} type="datetime-local" step="1" bind:value={pause.from} required/></div><div class="field"><label for={`pause-to-${pause.id}`}>Bis *</label><input id={`pause-to-${pause.id}`} type="datetime-local" step="1" bind:value={pause.to} required/></div><button class="icon-button" type="button" aria-label={`Pause ${index+1} entfernen`} onclick={()=>manualPauses=manualPauses.filter(p=>p.id!==pause.id)}><Icon name="trash" size={16}/></button></div>{/each}<button type="button" class="btn" style="align-self:flex-start" onclick={()=>manualPauses=[...manualPauses,{id:crypto.randomUUID(),from:'',to:''}]}><Icon name="plus" size={15}/>Pause hinzufügen</button><label class="check-field mt"><input type="checkbox" bind:checked={pausesReviewed} required/><span>Ich habe alle tatsächlich genommenen Pausen vollständig angegeben.</span></label></div>{#if manualAllocations.length}<section class="field full"><h3 style="font-size:16px;margin-top:8px">Arbeitszuordnungen dieser Sitzung</h3><p class="field-help">Die bisherigen Auftragswechsel bleiben einzeln sichtbar. Prüfen Sie die tatsächlichen Intervalle und passen Sie Zuordnungen nur bewusst an. Die Arbeitsintervalle müssen zur Sitzungszeit und zu den angegebenen Pausen passen.</p>{#each manualAllocations as allocation,index}<div class="manual-allocation"><div class="field-grid"><div class="field"><label for={`allocation-from-${allocation.id}`}>Arbeit {index+1} von *</label><input id={`allocation-from-${allocation.id}`} type="datetime-local" step="1" bind:value={allocation.from} required/></div><div class="field"><label for={`allocation-to-${allocation.id}`}>Bis *</label><input id={`allocation-to-${allocation.id}`} type="datetime-local" step="1" bind:value={allocation.to} required/></div><div class="field"><label for={`allocation-order-${allocation.id}`}>Auftrag</label><select use:searchableSelect={allocation.order_id} id={`allocation-order-${allocation.id}`} bind:value={allocation.order_id}><option value="">Zuordnung offen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div><div class="field"><label for={`allocation-activity-${allocation.id}`}>Tätigkeit *</label><input id={`allocation-activity-${allocation.id}`} bind:value={allocation.activity} required/></div></div><button type="button" class="btn small mt" disabled={manualAllocations.length<=1} onclick={()=>manualAllocations=manualAllocations.filter(a=>a.id!==allocation.id)}>Arbeitsintervall entfernen</button></div>{/each}<button type="button" class="btn" onclick={()=>manualAllocations=[...manualAllocations,{id:crypto.randomUUID(),from:'',to:'',order_id:'',activity:''}]}><Icon name="plus" size={15}/>Arbeitsintervall hinzufügen</button></section>{:else}<div class="field"><label for="manual-order">Auftrag</label><select use:searchableSelect={manualOrderId} id="manual-order" bind:value={manualOrderId}><option value="">Zuordnung offen</option>{#each orders as order}<option value={order.id}>{order.name}</option>{/each}</select></div><div class="field full"><label for="manual-activity">Tätigkeit *</label><input id="manual-activity" bind:value={activity} required maxlength="100" placeholder="Zum Beispiel Montage, Büro oder Fahrt"/></div>{/if}<div class="field full"><label for="manual-note">Anlass der Nacherfassung / Hinweis *</label><textarea id="manual-note" bind:value={manualNote} required minlength="3"></textarea></div><div class="field full"><label for="correction-reason">Begründung *</label><textarea id="correction-reason" bind:value={correctionReason} required minlength="5"></textarea></div></div>{/if}
</div><footer class="modal-footer"><button type="button" class="btn" onclick={()=>showManual=false} disabled={busy}>Abbrechen</button><button type="submit" class="btn primary" disabled={busy}>{busy?'Wird gespeichert …':showCorrection?'Antrag einreichen':'Zeitraum speichern'}</button></footer></form></div></div>{/if}

{#if submitReview}<div class="modal-backdrop" role="presentation"><div class="modal wide" role="dialog" aria-modal="true" aria-labelledby="submit-time-title" use:focusTrap tabindex="-1" onkeydown={e=>{if(e.key==='Escape'&&!busy)submitReview=false;}}><header class="modal-header"><div><h2 id="submit-time-title">Arbeitszeit vor der Abgabe prüfen</h2><p>{display(day,'date')} · {submissionIds.length} {submissionIds.length===1?'beendete Sitzung':'beendete Sitzungen'}</p></div><button class="icon-button" aria-label="Schließen" disabled={busy} onclick={()=>submitReview=false}><Icon name="close"/></button></header><div class="modal-body">{#if error}<div class="notice error" role="alert">{error}</div>{/if}<p class="mb">Arbeit: <strong>{durationText(dayWorkSeconds)}</strong> · Pausen: <strong>{durationText(dayBreakSeconds)}</strong></p><TimeSnapshot {data} snapshot={{segments:daySegments.map(s=>({...s,started_at:s.start_at,ended_at:s.end_at})),allocations:dayAllocations}}/><p class="field-help mt">Prüfen Sie die tatsächlichen Zeiten, Pausen und Zuordnungen. Mit der Abgabe wird dieser Stand zur sachlichen Prüfung eingereicht.</p></div><footer class="modal-footer"><button class="btn" disabled={busy} onclick={()=>submitReview=false}>Weiter bearbeiten</button><button class="btn primary" disabled={busy||selectedDayRunning||!submissionIds.length} onclick={submitDay}>{busy?'Wird eingereicht …':'Tag verbindlich einreichen'}</button></footer></div></div>{/if}
<style>
.timer-hero{border-radius:16px;background:var(--surface-raised,var(--paper));box-shadow:var(--panel-shadow,none)}.timer-fields{margin-top:4px}.day-totals{font-size:13px;color:var(--muted);margin-top:6px}.day-totals strong{color:var(--ink);font-weight:550;font-variant-numeric:tabular-nums}
.timer-actions .btn{white-space:nowrap;word-break:normal;overflow-wrap:normal;min-width:0}.timer-actions{flex-wrap:wrap}
.timer-topline{flex-wrap:wrap;row-gap:6px}
/* One compact save state instead of a chip, a banner and a footer line. */
.sync-line{display:inline-flex;align-items:center;gap:6px;margin:0;font-size:12px;line-height:1.4;color:var(--muted)}
.sync-line.subtle{color:var(--muted)}.sync-line.warning{color:var(--warning)}.sync-line.danger{color:var(--danger)}
.sync-line :global(svg){flex:none}
.sync-detail{margin:6px 0 0;font-size:12px;line-height:1.5;color:var(--warning)}
.current-assignment{display:flex;flex-direction:column;gap:3px;min-width:0;margin-top:14px;padding:12px 14px;border:1px solid var(--line);border-radius:10px;background:var(--input-surface)}
.current-activity{font-size:13px;color:var(--muted)}
.order-line{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:14px;line-height:1.5}
.order-line strong{font-weight:600}.order-title{color:var(--muted)}
.segment-info{min-width:0;flex:1}.segment-orders{display:flex;flex-direction:column;gap:2px}
.finish-card{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:14px 20px;padding:18px 20px;border:1px solid color-mix(in srgb,var(--forest) 30%,var(--line));border-radius:16px;background:var(--accent-wash,var(--wash))}
.finish-card:focus-visible{outline:2px solid var(--forest);outline-offset:3px}
.finish-card h2{font-size:18px;margin:0}.finish-card p{margin:4px 0 0;font-size:14px}.finish-card strong{font-variant-numeric:tabular-nums}
.submission-badge{display:inline-flex;align-items:flex-start;gap:8px;margin:0;padding:8px 12px;border-radius:10px;font-size:13px;line-height:1.5;font-weight:550;background:var(--wash);color:var(--ink)}
.submission-badge :global(svg){flex:none;margin-top:2px}
.submission-badge small{display:block;font-weight:400;font-size:12px;color:var(--ink)}
.submission-badge.warning{background:var(--warning-wash);color:var(--warning)}.submission-badge.success{background:var(--success-wash,var(--accent-wash,var(--wash)));color:var(--success,var(--forest))}.submission-badge.danger{background:var(--danger-wash);color:var(--danger)}
.submission-badge:focus-visible{outline:2px solid var(--forest);outline-offset:2px}
.day-footer{gap:12px}
.mobile-manual{display:none}
/* Simple manual entry */
.day-pick{display:flex;flex-wrap:wrap;gap:8px}.day-pick input{flex:1 1 120px;min-width:0}.day-pick .chip{padding:8px 12px}
.field-pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
.chip-field{border:0;margin:0;padding:0;min-width:0}.chip-field legend{padding:0;margin-bottom:8px;font-size:13px;font-weight:500}
.chips{display:flex;flex-wrap:wrap;gap:8px;margin-top:8px}.chip-field .chips{margin-top:0}
.chip{position:relative;display:inline-flex;align-items:center;justify-content:center;min-width:48px;min-height:44px;padding:8px 14px;border:1px solid var(--line);border-radius:999px;background:var(--paper);color:var(--ink);font:inherit;font-size:14px;cursor:pointer}
.chip-field .chips{gap:5px}.chip-field .chip{min-width:44px;padding:8px 9px}
.chip input{position:absolute;inset:0;width:100%;height:100%;margin:0;opacity:0;cursor:pointer}
.chip:has(input:checked),.chip[aria-pressed=true]{border-color:var(--forest);background:var(--accent-wash,var(--wash));color:var(--forest);font-weight:600}
.chip:has(input:focus-visible),.chip:focus-visible{outline:2px solid var(--forest);outline-offset:2px}
.inline-link{display:inline;min-height:0;padding:0;border:0;background:none;color:var(--forest);font:inherit;text-decoration:underline;text-underline-offset:3px;cursor:pointer}
.manual-preview{margin:0;padding:12px 14px;border-radius:10px;background:var(--input-surface,var(--wash));font-size:14px}
@media (max-width:760px){
  /* Keep the timer and its primary action above the fixed navigation. */
  .heading-intro,.heading-manual{display:none}
  .page-heading{margin-bottom:14px}.page-heading h1{font-size:24px}
  .mobile-manual{display:flex;width:100%}
  .timer-hero{padding:18px 16px}
  .timer-hero .timer-readout{margin:10px 0 4px;font-size:58px}
  .timer-intro{display:none}
  .timer-hero .timer-description{margin-bottom:0}
  .timer-fields{margin-top:14px}
  .timer-actions{position:sticky;bottom:calc(76px + env(safe-area-inset-bottom));z-index:4;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin:14px -8px -8px;padding:8px;border-radius:14px;background:var(--surface-raised,var(--paper))}
  .timer-actions .btn{width:100%;min-width:0}
  .timer-actions{container-type:scroll-state}
  @container scroll-state(stuck: bottom){.timer-actions::before{content:'';position:absolute;inset:0;z-index:-1;border-radius:inherit;box-shadow:0 -10px 22px -12px light-dark(rgb(20 34 56 / .38),rgb(0 0 0 / .7));pointer-events:none}}
  .timer-actions .btn.primary,.timer-actions .btn:only-child,.timer-actions .btn:last-child:nth-child(2){grid-column:1/-1}
  .timer-actions .btn:not(.primary){min-height:50px}
  .finish-card{padding:16px}.finish-card .btn{width:100%}
  .day-footer .btn{width:100%}
  :global(.app-shell:has(.time-view) .assistant-trigger){display:none}
}
</style>
